import os,re,collections
root='AlgebraicJacobian'
imports={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mod=p[:-5].replace('/','.')
            deps=[]
            for line in open(p,encoding='utf8',errors='ignore'):
                m=re.match(r'import\s+(AlgebraicJacobian\S*)',line)
                if m: deps.append(m.group(1))
                elif line.strip() and not line.startswith('import') and not line.startswith('/-') and not line.startswith('-') and 'Copyright' not in line and not line.startswith('*'):
                    pass
            imports[mod]=deps

def closure(m):
    seen=set(); st=[m]
    while st:
        x=st.pop()
        for d in imports.get(x,[]):
            if d not in seen: seen.add(d); st.append(d)
    return seen

target='AlgebraicJacobian.RiemannRoch.WindowLedgerF3'
# the hb carriers
carriers=[l.strip() for l in os.popen("grep -rl 'hb : 0 < windowBound' AlgebraicJacobian/").read().split()]
carriers=[c[:-5].replace('/','.') for c in carriers]
print(f"{'module':62s} {'WindowLedgerF3 in cone?':22s}")
reach=[];noreach=[]
for c in sorted(carriers):
    cl=closure(c)
    ok = target in cl
    (reach if ok else noreach).append(c)
    print(f"{c.replace('AlgebraicJacobian.Picard.',''):62s} {'YES' if ok else 'NO  <-- INVERSION'}")
print()
print("reachable:",len(reach)," NOT reachable:",len(noreach))
EOF

